const uiLocaleKey = 'ls-cms-interface-language-v1';
const supportedUiLocales = new Set(['en','zh','ms']);
const uiCopyFor = (value) => {
  const normalized = String(value ?? '').trim();
  const entry = uiCopy.find((row) => row.some(copy=>String(copy).trim()===normalized));
  return entry?.[['en','zh','ms'].indexOf(uiLocale)] || normalized;
};
const uiPhrase = (en,zh,ms) => ({en,zh,ms}[uiLocale]||en);
function applyCmsLocale(){
  document.documentElement.lang=uiLocale;
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(node.parentElement?.closest('[data-cms-content]'))continue;const value=node.nodeValue;if(value?.trim()){const translated=uiCopyFor(value);if(translated!==value)node.nodeValue=translated;}}
  queryAll('[aria-label],[title],[placeholder]').forEach(element=>{if(element.closest('[data-cms-content]'))return;['aria-label','title','placeholder'].forEach(attribute=>{const value=element.getAttribute(attribute);if(value){const translated=uiCopyFor(value);if(translated!==value)element.setAttribute(attribute,translated);}});});
  if(typeof state!=='undefined'&&!state.selectedMedia&&$('#media-details-heading')){const heading=$('#media-details-heading');const label=uiCopyFor('Edit media details');if(heading.textContent!==label)heading.textContent=label;}
}
const statusLabel = (value) => {
  const label=String(value||'').replaceAll('_',' ').replace(/\b\w/g,letter=>letter.toUpperCase());
  return uiCopyFor(label);
};
let uiLocale = 'en';
try { const saved = localStorage.getItem(uiLocaleKey); if (supportedUiLocales.has(saved)) uiLocale = saved; } catch {}
