const queryAll=(selector,root=document)=>Array.from(root.querySelectorAll(selector));const clone=value=>value==null?value:JSON.parse(JSON.stringify(value)), humanize=value=>String(value||'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[_-]+/g,' ').replace(/^./,c=>c.toUpperCase());
