function chooseCmsLocale(locale){if(!supportedUiLocales.has(locale))return;uiLocale=locale;try{localStorage.setItem(uiLocaleKey,locale);}catch{}$('#ui-language').value=locale;applyCmsLocale();setTypes();renderRecords();renderDashboard();renderReviewQueue();renderMedia();if(state.selected)renderEditor();if(state.settings)renderSettings({available:true,data:{settings:state.settings}});if(state.migrationPreview)renderMigrationPreview(state.migrationPreview);if(state.view==='history')refreshHistory();}
async function api(url,options={}){
  const method=options.method||'GET',headers=Object.assign({},options.headers||{});
  if(options.body!==undefined)headers['Content-Type']='application/json';if(options.rawBody!==undefined)headers['Content-Type']=options.contentType||'application/octet-stream';
  if(!['GET','HEAD'].includes(method)&&state.csrf)headers['X-CSRF-Token']=state.csrf;
  try{const response=await fetch(url,{method,headers,body:options.body===undefined?options.rawBody:JSON.stringify(options.body),credentials:'same-origin'});const data=response.status===204?{}:await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.error||'Request failed ('+response.status+').');error.status=response.status;throw error;}return data;}
  catch(error){if(error instanceof TypeError)throw new Error('The CMS could not reach its server. Check that the local website and CMS services are running.');throw error;}
}
async function optionalApi(url,options={}){
  try{return {available:true,data:await api(url,options)};}
  catch(error){if([401,403,404,405,501].includes(error.status))return {available:false,restricted:[401,403].includes(error.status),error};throw error;}
}
