  const hasRegistry=Array.isArray(state.registry?.routes),routes=hasRegistry?state.registry.routes.map(route=>({route,record:state.records.find(item=>item.id===route.contentId||normalizedRoute(item.route)===normalizedRoute(route.path||route.route))||null})):state.records.map(record=>({route:{path:record.route,title:titleFor(record),type:record.type},record}));
