  const total=hasRegistry?state.registry.routes.length:state.records.length;$('#record-count').textContent=entries.length+' / '+total;$('#pages-summary').textContent=hasRegistry?total+' registered website paths · '+state.records.length+' saved content records':state.records.length+' CMS page records';
