function updatePath(object,path,value){let current=object;for(let i=0;i<path.length-1;i++){if(current[path[i]]==null||typeof current[path[i]]!=='object')current[path[i]]=typeof path[i+1]==='number'?[]:{};current=current[path[i]];}if(path.length)current[path[path.length-1]]=value;}
