    const label=document.createElement('label');label.className='media-association';const check=document.createElement('input');check.type='checkbox';check.value=media.id;check.checked=selected.has(media.id);
    const preview=document.createElement('span');preview.className='association-thumb';if(media.mimeType?.startsWith('image/')){const image=document.createElement('img');image.src='/api/cms/media/'+encodeURIComponent(media.id);image.alt='';preview.append(image);}else preview.textContent=media.mimeType?.startsWith('video/')?'▶':'PDF';
    const info=document.createElement('span');info.className='association-info';const title=document.createElement('strong');title.textContent=media.altTexts?.en?.alt||media.sourceUrl||media.id;const detail=document.createElement('small');detail.textContent=media.mimeType+' · '+humanize(media.matchStatus);info.append(title,detail);label.append(check,preview,info);root.append(label);
