function renderWorkflow(){
  const panel=$('#review-actions');panel.replaceChildren();panel.hidden=true;const revision=state.selected?.revision;if(!revision)return;
  const status=document.createElement('p');status.className='workflow-explanation';status.textContent=uiCopyFor('Status')+': '+statusLabel(revision.status);panel.append(status);
  const technicalReviewRequired=state.selected.type==='machine'||state.selected.type==='video_library'||Boolean(revision.fields?.data?.videoPlacements?.length);
  if(state.user.role==='technical_reviewer'&&technicalReviewRequired&&revision.status==='review_requested'){
    const note=document.createElement('textarea');note.id='technical-note';note.rows=2;note.placeholder=uiCopyFor('Review note (optional)');note.setAttribute('aria-label',uiCopyFor('Technical review note'));
    const approve=document.createElement('button');approve.type='button';approve.className='button primary';approve.textContent=uiCopyFor('Approve this revision');approve.addEventListener('click',()=>review('approved'));
    const changes=document.createElement('button');changes.type='button';changes.className='button';changes.textContent=uiCopyFor('Request changes');changes.addEventListener('click',()=>review('changes_requested'));panel.append(note,approve,changes);panel.hidden=false;
  }
  const canPublish=['publisher','admin'].includes(state.user.role)&&(technicalReviewRequired?revision.status==='ready_to_publish':revision.status==='review_requested');
  if(canPublish){const hint=document.createElement('p');hint.textContent=uiCopyFor('Confirm and publish')+' · '+uiCopyFor('Revision')+' '+revision.revisionNumber;const button=document.createElement('button');button.type='button';button.className='button primary';button.textContent=uiCopyFor('Confirm and publish');button.addEventListener('click',publish);panel.append(hint,button);panel.hidden=false;}
}
