function appendReportList(root,title,entries){if(!Array.isArray(entries)||!entries.length)return;const section=document.createElement('section');section.className='migration-report-list';const heading=document.createElement('h4');heading.textContent=uiCopyFor(title);const list=document.createElement('ul');entries.forEach(entry=>{const item=document.createElement('li');item.dataset.cmsContent='';item.textContent=typeof entry==='string'?entry:[entry.title,entry.path,entry.message,entry.reason].filter(Boolean).join(' · ')||JSON.stringify(entry);list.append(item);});section.append(heading,list);root.append(section);}
