  const route=routeData?.route||'';const parts=route.split('/').filter(Boolean);const type=TYPE_NAMES[routeData?.type]?routeData.type:'home';state.selected={type,slug:parts.at(-1)||'',route,version:0,revision:null};state.editFields=blankFields();if(routeData?.title)state.editFields.translations.en.title=routeData.title;state.editLocale='en';renderEditor();setView('pages');$('#content-slug').focus();
