  missing.forEach(field=>{if(!(field.key in state.editFields.data))state.editFields.data[field.key]=fieldDefault(field);});renderEditor();const target=$('#data-editor [data-field-key="'+CSS.escape(missing[0].key)+'"]');target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});target?.querySelector('input,textarea,button')?.focus();notice(uiCopyFor('Complete required fields before saving.'),true);return false;
