async function publish(){
  const revision=state.selected?.revision;if(!revision)return;
  if(!window.confirm(uiCopyFor('Publish revision')+' '+revision.revisionNumber+'? '+uiCopyFor('This action makes it public.')))return;
  try{const result=await api('/api/cms/content/'+encodeURIComponent(state.selected.id)+'/publish',{method:'POST',body:{confirmPublish:true,revisionId:revision.id,confirmRevisionId:revision.id,expectedVersion:state.selected.version}});if(result.content){state.selected=result.content;state.editFields=fieldsFor(result.content);}if(result.job){startPublicationPolling(result.job);notice('Publication started. The previous website remains active until the new release is ready.');}else{await refreshRecords();renderEditor();notice('The confirmed revision is now public.');}}
  catch(error){notice(error.message,true);}
}
function startPublicationPolling(job){
  if(state.publicationJobTimer)clearTimeout(state.publicationJobTimer);const update=Object.assign({},state.dashboard?.publication||{},job);state.dashboard=Object.assign({},state.dashboard||{},{publication:update});renderReleaseStatus();
  const poll=async()=>{try{const result=await api('/api/cms/publication-jobs/'+encodeURIComponent(job.id)),current=result.job||result;state.dashboard=Object.assign({},state.dashboard||{},{publication:Object.assign({},state.dashboard?.publication||{},current)});renderReleaseStatus();if(current.status==='active'){state.publicationJobTimer=null;await refreshRecords();await refreshOptionalWorkspace();renderDashboard();notice('The new website release is active.');return;}if(current.status==='failed'){state.publicationJobTimer=null;notice(current.message||'The website release failed. The previous release remains active.',true);return;}state.publicationJobTimer=setTimeout(poll,1200);}catch(error){state.publicationJobTimer=null;notice('Publication progress could not be checked: '+error.message,true);}};
  if(job.status==='active'){refreshRecords().then(refreshOptionalWorkspace).then(renderDashboard);return;}if(job.status==='failed'){notice(job.message||'The website release failed. The previous release remains active.',true);return;}state.publicationJobTimer=setTimeout(poll,800);
}
