$('#migration-form').addEventListener('submit',async event=>{
  event.preventDefault();const file=new FormData(event.currentTarget).get('archive');if(!(file instanceof File)||!file.size)return;state.migrationPreview=null;$('#migration-preview').hidden=true;message($('#migration-message'),'Inspecting archive…');$('#migration-progress').hidden=false;
  try{const result=await api('/api/cms/migration/preview',{method:'POST',rawBody:file,contentType:file.type||'application/octet-stream',headers:{'X-File-Name':file.name}});state.migrationPreview=result;renderMigrationPreview(result);message($('#migration-message'),'Review the source items and map each item you want to import.');}
  catch(error){if([404,405,501].includes(error.status))renderMigration({available:false,error});message($('#migration-message'),error.message,true);}
  finally{$('#migration-progress').hidden=true;}
});
async function importMigration(){
  const preview=state.migrationPreview;if(!preview?.previewId)return;const mappings={};queryAll('#migration-preview [data-migration-identity]').forEach(input=>{const identity=input.dataset.migrationIdentity;if(!mappings[identity])mappings[identity]={};if(input.dataset.migrationType)mappings[identity].type=input.value;if(input.dataset.migrationRoute)mappings[identity].route=input.value.trim();});
  Object.keys(mappings).forEach(identity=>{if(!mappings[identity].type||!mappings[identity].route)delete mappings[identity];});if(!Object.keys(mappings).length){message($('#migration-message'),'Choose a page type and enter a website path for at least one supported source item.',true);return;}
  if(!window.confirm('Import the mapped source items as private drafts?'))return;
  const button=$('#migration-import');if(button)button.disabled=true;
  try{const result=await api('/api/cms/migration/import',{method:'POST',body:{previewId:preview.previewId,confirm:true,mappings}});const job=result.job||{};const progress=Number.isFinite(Number(job.progress))?' · '+Math.round(Number(job.progress))+'%':'';message($('#migration-message'),'Import job '+(job.id||'created')+' · '+humanize(job.status||'accepted')+progress+'. Imported items will remain drafts until reviewed.');}
  catch(error){message($('#migration-message'),error.message,true);if([404,405,501].includes(error.status))renderMigration({available:false,error});}
  finally{if(button?.isConnected)button.disabled=false;}
}
